class UserRepository {
  async findByEmail(email: string): Promise<User | null> {
    const row = await db.query("SELECT * FROM users WHERE email=$1", [email]);
    return row ? new User(row.id, row.email) : null;
  }
  async save(user: User): Promise<void> {
    await db.query("UPDATE users SET email=$1 WHERE id=$2", [user.email, user.id]);
  }
}

// Business logic depends only on the repository's interface
async function getUserOrders(email: string, repo: UserRepository, orders: OrderRepository) {
  const user = await repo.findByEmail(email);
  return user ? orders.findByUserId(user.id) : [];
}
